// PF이익분배금 조회

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.checkCond();
        $c.cm.fn_jongMok(txb_IsuCd, txb_IsuNm, SECUGRP_ID_PF, "0", "A");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15920.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.checkCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15920.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF15920.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "PF 이익금분배 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15920.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DsclList.errorMsg) {
            await $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page); // 총 건수

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15920.dts_DsclList_OnLoadCompleted" });
    }
};

