 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name Grd_jong_mok_OnKeyPress
 * @description Grd jong mok On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_jong_mok_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_jongMok_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.Grd_jong_mok_OnKeyPress" });
    }
};

