/**
 * @method
 * @name Grd_jong_mok_OnClick
 * @description Grd_jong_mok 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_jong_mok_OnClick = function(row, colid) {
    try {
        Grd_jong_mok.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.Grd_jong_mok_OnClick" });
    }
};

/**
 * @method
 * @name Grd_jong_mok_OnSetFocus
 * @description Grd jong mok On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_jong_mok_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.Grd_jong_mok_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_jong_mok_OnKillFocus
 * @description Grd_jong_mok 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_jong_mok_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_jong_mok.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.Grd_jong_mok_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_jong_mok_OnFilter
 * @description Mx Data Set jong mok On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_jong_mok_OnFilter = function(row) {
    try {
        if (skw !== "") {
            f1 = MxDataSet_jong_mok.getCellData(row, "ISU_KOR_ABBRV");
            f2 = MxDataSet_jong_mok.getCellData(row, "ISU_CD");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.MxDataSet_jong_mok_OnFilter" });
    }
};

