/**
 * @method
 * @name txb_IsuCd_onblur
 * @description txb_IsuCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsuCd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_jong_mok.style.display = "none";
        }
        if (txb_IsuCd.getValue() === "") {
            txb_IsuNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.txb_IsuCd_onblur" });
    }
};

/**
 * @method
 * @name txb_IsuCd_onfocus
 * @description txb_IsuCd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsuCd_onfocus = function() {
    try {
        Grd_jong_mok.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.txb_IsuCd_onfocus" });
    }
};

/**
 * @method
 * @name txb_IsuCd_onkeyup
 * @description txb_IsuCd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsuCd_onkeyup = function() {
    try {
        if (txb_IsuCd.getValue() === "") {
            Grd_jong_mok.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_jong_mok.focus();
            } else {
                $c.cm.fn_jongMok_nm(window.event.keyCode);
                // txtTest.value = window.event.keyCode;

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.txb_IsuCd_onkeyup" });
    }
};

