        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15920.MxDataSet_jong_mok_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DsclSearchPF.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 12)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};

/**
 * @method
 * @name checkCond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    await scwin.search();
};
